_DEFAULT_ROOT_TOLERANCE_MM = 1.0e-21
_DEFAULT_MAX_ROOT_ITERATIONS = 96
_DEFAULT_GRADIENT_RELATIVE_STEP = 1.0e-4
_DEFAULT_GRADIENT_MINIMUM_STEP_MM = 1.0e-15
_SOURCE_ACCELERATION_SEMANTICS = {"instantaneous", "preceding_interval"}


def _sum_source_terms(terms: np.ndarray) -> np.ndarray:
    """Faithfully sum source-indexed components, independently of traversal order.

    Source kernels (including Numba kernels) return individual contributions;
    reduction stays here, with no fast-math reassociation or lost low-order sum.
    Empty and excluded source rows contribute zero.
    """
    shape = terms.shape[1:]
    flattened = terms.reshape(terms.shape[0], int(np.prod(shape)))
    return np.asarray([fsum(column) for column in flattened.T]).reshape(shape)


def _validated_source_acceleration_semantics(value: str) -> str:
    selected = str(value).strip().lower()
    if selected not in _SOURCE_ACCELERATION_SEMANTICS:
        allowed = ", ".join(sorted(_SOURCE_ACCELERATION_SEMANTICS))
        raise ValueError(f"source_acceleration_semantics must be one of: {allowed}")
    return selected


class RetardedHistoryError(ValueError):
    """Raised when a source history does not bracket a retarded event."""


@dataclass(frozen=True)
class ObserverEvent:
    """One observer event in the solver's millimetre/nanosecond units."""

    time_ns: float
    position_mm: tuple[float, float, float]
    time_low_ns: float = 0.0
    position_low_mm: tuple[float, ...] = (0.0, 0.0, 0.0)
    time_tail_ns: float = 0.0
    position_tail_mm: tuple[float, ...] = (0.0, 0.0, 0.0)

    def __post_init__(self) -> None:
        time = float(self.time_ns)
        position = np.asarray(self.position_mm, dtype=float)
        if (
            not np.isfinite(self.time_low_ns)
            or not np.isfinite(self.time_tail_ns)
            or np.asarray(self.position_tail_mm).shape != (3,)
            or not np.all(np.isfinite(self.position_tail_mm))
            or np.asarray(self.position_low_mm).shape != (3,)
            or not np.all(np.isfinite(self.position_low_mm))
        ):
            raise ValueError("observer coordinate remainders must be finite")
        if not np.isfinite(time):
            raise ValueError("observer time must be finite")
        if position.shape != (3,) or not np.all(np.isfinite(position)):
            raise ValueError("observer position must contain three finite values")


def _shift_resolved_coordinate(
    high: float, low: float, tail: float, shift: float
) -> tuple[float, float, float]:
    """Apply a stencil displacement without discarding its rounding remainder."""
    from decimal import Decimal, localcontext

    with localcontext() as context:
        context.prec = 80
        d = Decimal.from_float
        value = d(high) + d(low) + d(tail) + d(shift)
        new_high = float(high + shift)
        new_low = float(value - d(new_high))
        new_tail = float(value - d(new_high) - d(new_low))
        return new_high, new_low, new_tail


@dataclass(frozen=True)
class RetardedChargeFieldResult:
    """Total native Gaussian charge potential, field, and diagnostics.

    ``four_potential`` is the contravariant Lienard--Wiechert potential
    ``A^mu=(phi, phi beta)`` in the gauge selected by the retarded point-charge
    solution.  It is appended with a default to preserve compatibility with
    older direct dataclass constructors.
    """

    electric_field_native: np.ndarray
    magnetic_field_native: np.ndarray
    field_tensor: np.ndarray
    retarded_time_ns: np.ndarray
    light_cone_residual_mm: np.ndarray
    separation_mm: np.ndarray
    valid_sources: np.ndarray
    four_potential: np.ndarray = dataclass_field(
        default_factory=lambda: np.zeros(4, dtype=float)
    )

    retarded_time_error_bound_ns: np.ndarray | None = None


@dataclass(frozen=True)
class RetardedMutualChargeFieldMatrix:
    """Per-observer, per-source fields with optional matching-index omission.

    The first index selects the observer event and the second selects the
    source worldline. Same-grid callers normally omit matching indices;
    distinct-grid callers can retain every source--observer pair.
    """

    electric_field_native: np.ndarray
    magnetic_field_native: np.ndarray
    four_potential: np.ndarray
    retarded_time_ns: np.ndarray
    light_cone_residual_mm: np.ndarray
    separation_mm: np.ndarray
    valid_sources: np.ndarray


@dataclass(frozen=True)
class RetardedChargeFieldGradientResult:
    """A native charge field and its complete potential/field derivatives.

    ``partial_a[lambda, nu]`` is ``partial_lambda A^nu`` per millimetre and
    uses the same eight independently retarded stencil events as
    ``partial_f``.  It is appended with a default to preserve compatibility
    with older direct dataclass constructors.
    """

    field: RetardedChargeFieldResult
    partial_f: np.ndarray
    stencil_step_mm: float
    stencil_retarded_time_ns: np.ndarray
    partial_a: np.ndarray = dataclass_field(
        default_factory=lambda: np.zeros((4, 4), dtype=float)
    )


@dataclass(frozen=True)
class RetardedChargeResponseGradientResult:
    """Potential plus the independent coefficients of ``F`` and ``partial F``.

    The analytical path keeps only the six antisymmetric coefficients and
    their four directional derivatives.  ``fallback_used`` is true when the
    retarded root is too close to an interpolation-segment boundary for the
    within-segment derivative to be authoritative; in that case the values
    are packed from the maintained centered-stencil provider.
    """

    four_potential: np.ndarray
    partial_a: np.ndarray
    antisymmetric_response: np.ndarray
    partial_antisymmetric_response: np.ndarray
    retarded_time_ns: np.ndarray
    light_cone_residual_mm: np.ndarray
    separation_mm: np.ndarray
    valid_sources: np.ndarray
    kappa: np.ndarray
    segment_index: np.ndarray
    minimum_segment_margin_ratio: float
    fallback_used: bool
    fallback_reason: str | None
    fallback_stencil_step_mm: float | None
    partial_antisymmetric_response_along_velocity: np.ndarray | None = None
    directional_unavailable_reason: str | None = None
    directional_jet_residual: np.ndarray | None = None

    retarded_time_error_bound_ns: np.ndarray | None = None


